/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import page2020.core.App;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Content;import page2020.view.H5;import page2020.view.bs4.B4border;import page2020.view.bs4.B4button;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.AlignSelf;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4show.Justify;import page2020.view.bs4.B4show.P;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3color.White;import page2020.view.css3.C3show.Overflow;import page2020.view.css3.C3show.Position;import page2020.view.css3.C3show.Visible;public class Udialog extends B4element {	private static final String dialog_dialog = "dialog";	private static final String dialog_pop = "pop";	private static final String dialog_close = "close";	private static final String dialog_btnBox = "button_box";	private static final String talk_device = "device";	public Udialog() {		super();	}	public Udialog(String device, Content<?>... contents) {		this("auto", "1rem", false, 1, B4.element().data(talk_device, device).append(contents));	}	public Udialog(String device, boolean pop, Content<?>... contents) {		this("auto", "1rem", pop, 1, B4.element().data(talk_device, device).append(contents));	}	public Udialog(String device, String height, Content<?>... contents) {		this("auto", "1rem", true, 1, B4.element().data(talk_device, device).height(height).append(contents));	}	public Udialog(String width, String padding, boolean pop, int zindex, B4element element) {		super.name(PageKey.desktop)			.data(dialog_pop, Boolean.valueOf(pop))			.cssClass(D.flex)			.css(C3.bg("rgba(0,0,0,0.5)"))			.css(C3.show.visibility(Visible.hidden))			.css(C3.show.position(Position.absolute))			.css(C3.box.top("0"), C3.box.left("0"), C3.width("100%"), C3.height("100%"))			.css(C3.show.zIndex(zindex));		super.append(B4.element()			.name(PageKey.dialog)			.css(C3.width(width))			.css(C3.show.zIndex(zindex + 1))			.cssClass(P.mxAuto, Justify.center, AlignSelf.center)			.data("width", width)			.append(				B4.element()					.cssClass(TextX.right)					.css(C3.height("2rem"))					.append(						H5.span().data(dialog_dialog, dialog_close)							.css(C3.color(White.White))							.append(H5.icon("times").size("2x"))					),				B4.element()					.mt(2).cssClass(B4border.round)					.css(C3.bg(White.White), C3.padding(padding))					.append(						element.name(PageKey.talk).p(1)							.css(C3.show.overflowX(Overflow.hidden), C3.show.overflowY(Overflow.auto))					)			)		);	}	public B4element board() {		B4element dialog = (B4element) super.get(0);		B4element board = (B4element) dialog.get(1);			return board;	}	public B4element buttons(String... buttons) {		if (EmptyUtil.is(buttons)) {			return null;		}		B4element btnBox = B4.element().mt(3).cssClass(TextX.center);		btnBox.data(dialog_dialog, dialog_btnBox);		for (int i=0; i < buttons.length; i++) {			B4button button = App.button(buttons[i]);			if (button != null) {				button.name(null);				button.data(PageKey.operate, buttons[i]);				button.css(C3.padding("0.25rem 2.5rem"), C3.margin("0.25rem 0.5rem 0 0.5rem"));				button.css(C3.border.radius("1rem"));				btnBox.append(button);			}		}		this.board().append(btnBox);		return btnBox;	}}